// single-item input: one status callback, one call.
//
// Read the webhook by name: `Settings` sits between the two and a Set node in
// manual mode replaces the item, so $input here would be the config.
const req = $('A Call Comes In').first().json;
const cfg = $('Settings').first().json;

// Twilio posts form-encoded, so the fields land under `body` as strings. A test
// from a REST client will send JSON instead, and both shapes are accepted here
// because the version that only handles one is the version that works in
// testing and not in production.
const b = req.body || req.query || req;

function pick(...names) {
  for (const n of names) {
    if (b[n] != null && b[n] !== '') return String(b[n]);
    const lower = Object.keys(b).find((k) => k.toLowerCase() === n.toLowerCase());
    if (lower && b[lower] != null && b[lower] !== '') return String(b[lower]);
  }
  return '';
}

const status = pick('CallStatus', 'call_status').toLowerCase();
const direction = pick('Direction', 'direction').toLowerCase();
const from = pick('From', 'from', 'Caller');
const to = pick('To', 'to', 'Called');

// Twilio's documented terminal statuses. `no-answer` is hyphenated - matching
// `noanswer` or `no_answer` silently texts nobody, and that failure looks
// exactly like everything working.
const MISSED = ['busy', 'no-answer', 'failed', 'canceled'];

// Only inbound calls. An outbound call your own team placed and abandoned must
// never trigger a "sorry we missed you" to the person you rang.
const inbound = direction.indexOf('inbound') !== -1 || direction === '';

const digits = String(from).replace(/[^\d+]/g, '');

// Opening hours, as "09:00-17:30" in the workflow's own timezone.
const hours = String(cfg.opening_hours || '09:00-17:30');
const parts = hours.split('-');
const openMin = (function (t) {
  const m = String(t).trim().match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : 9 * 60;
})(parts[0]);
const closeMin = (function (t) {
  const m = String(t).trim().match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : 17 * 60 + 30;
})(parts[1]);

const now = $now;
const minutes = now.hour * 60 + now.minute;
// Luxon weekdays are 1=Monday..7=Sunday.
const openDays = String(cfg.open_days || '1,2,3,4,5')
  .split(',').map((d) => Number(d.trim())).filter((d) => d >= 1 && d <= 7);

const dayOpen = openDays.indexOf(now.weekday) !== -1;
const withinHours = dayOpen && minutes >= openMin && minutes < closeMin;

return [{ json: {
  call_id: pick('CallSid', 'call_sid') || ('call-' + now.toMillis()),
  from: digits,
  to,
  status,
  direction,
  missed: MISSED.indexOf(status) !== -1 && inbound,
  within_hours: withinHours,
  opening_hours: hours,
  received_at: now.toISO(),
}}];

// Who is this, and should we text at all?
//
// Three sources meet here: what the call was, who the sheet says they are, and
// whether we already texted them. Reading them by name rather than from $input
// because the Sheets read and the Data Table read are separate branches.
const cfg = $('Settings').first().json;
const call = $('Read The Call').first().json;

// The customer sheet. alwaysOutputData means an empty sheet still emits one
// empty item rather than ending the branch.
const customers = $('Look Them Up').all().map((x) => x.json).filter((r) => r && r.phone);

// Compare on digits only. A sheet written by a human contains "07700 900123",
// "+1234567890" and "(07700) 900123" for the same person.
function digits(s) { return String(s || '').replace(/\D/g, ''); }
// Match on the last nine digits, which survives the country code being present
// on one side and absent on the other.
function tail(s) { const d = digits(s); return d.slice(-9); }

const callerTail = tail(call.from);
const known = callerTail
  ? customers.find((c) => tail(c.phone) === callerTail)
  : null;

// Have we already texted this number recently? A caller who cannot reach you
// rings three times in a row, and three identical texts reads as a malfunction.
const seen = $('Have We Texted Recently?').all().map((x) => x.json).filter((r) => r && r.phone);
const prior = callerTail ? seen.find((r) => tail(r.phone) === callerTail) : null;

const quietMinutes = Number(cfg.quiet_minutes || 60);
let minutesSince = null;
if (prior && prior.texted_at) {
  const then = Date.parse(prior.texted_at);
  if (!isNaN(then)) minutesSince = Math.round((Date.now() - then) / 60000);
}
const textedRecently = minutesSince !== null && minutesSince < quietMinutes;

// The three cases the owner genuinely wants told apart.
const caller_type = !call.within_hours ? 'after_hours' : (known ? 'known_customer' : 'new_lead');

return [{ json: Object.assign({}, call, {
  known: !!known,
  customer_name: known ? String(known.name || '').trim() : '',
  customer_notes: known ? String(known.notes || '').slice(0, 200) : '',
  times_called_before: prior ? Number(prior.call_count || 1) : 0,
  minutes_since_last_text: minutesSince,
  texted_recently: textedRecently,
  caller_type,
  should_text: call.missed && !textedRecently,
  business_name: String(cfg.business_name || 'us'),
}) }];

parameters.text:
=Write one SMS replying to a phone call this business just missed.

Business: {{ $json.business_name }}
Opening hours: {{ $json.opening_hours }}
Called during opening hours: {{ $json.within_hours ? 'yes' : 'no' }}
Already a customer: {{ $json.known ? 'yes' : 'no' }}
Their name, if known: {{ $json.customer_name || '(unknown)' }}
What we know about them: {{ $json.customer_notes || '(nothing)' }}

Under 220 characters. Plain sentences, no emoji, no markdown, no links, no placeholders like [name] - if you do not have their name, do not use one.

Apologise once, briefly. Say when someone will get back to them, using the opening hours if they rang outside them. Invite them to reply with what they need.

Write only what the customer should read. Never explain your own reasoning to them: a live run produced "reply, it is cheaper for both of us than another call", which is this instruction leaking into the message.

If they are already a customer, greet them by name and sound like you know them. If they are not, say who the business is in three or four words.

Do not promise a time you were not given, do not quote a price, and do not claim anyone is 'on another call'. Return the message text only.

