// single-item input: the chain runs executeOnce for this one caller.
//
// The cap is the point. SMS bills per 160-character segment, so a model that
// writes 400 characters triples the cost of every missed call in the country.
// A prompt asking for brevity is a request; a slice is a guarantee.
const decided = $('Decide What To Do').first().json;
const raw = $input.first().json || {};

let text = String(raw.text || raw.response || raw.output || '').trim();
// Strip anything that would render as literal characters in an SMS.
text = text.replace(/\*\*([^*\n]+)\*\*/g, '$1').replace(/[*_`#]/g, '');

// Smart punctuation down to ASCII, and this is a billing fix rather than a
// cosmetic one. SMS uses the GSM-7 alphabet at 160 characters per segment; a
// single character outside it forces the entire message to UCS-2, where a
// segment is 70. Measured live on 2026-08-26: a 178-character reply containing
// one curly apostrophe billed as two segments instead of one.
text = text
  .replace(/[\u2018\u2019\u201b]/g, "'")
  .replace(/[\u201c\u201d]/g, '"')
  .replace(/[\u2013\u2014]/g, '-')
  .replace(/\u2026/g, '...')
  .replace(/\u00a0/g, ' ');

text = text.replace(/\s+/g, ' ').trim();

// Cut on a sentence end if there is one in range, so the message never stops
// mid-word.
const LIMIT = 300;
if (text.length > LIMIT) {
  const cut = text.slice(0, LIMIT);
  const stop = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  text = stop > 120 ? cut.slice(0, stop + 1) : cut.trim();
}

if (!text) {
  // Never send nothing, and never send a model error. A plain fallback is a
  // better missed-call reply than silence.
  text = 'Sorry we missed your call. Reply here with what you need and we will '
       + 'come back to you as soon as we can.';
}

// Report the segment count honestly rather than optimistically. Anything left
// outside GSM-7 still bills at 70 characters per segment, and the owner should
// see that in Slack rather than discover it on the invoice.
// Written as a loop rather than a regex on purpose. The regex version needs a
// negated character class spanning the whole GSM-7 set, which is unreadable and
// easy to get subtly wrong; a character-by-character scan says what it means.
const GSM_EXTRA = '\u00a3\u00a5\u00e8\u00e9\u00f9\u00ec\u00f2\u00c7\u00d8\u00f8\u00c5\u00e5'
                + '\u00c6\u00e6\u00df\u00c9\u00a1\u00c4\u00d6\u00d1\u00dc\u00a7\u00bf'
                + '\u00e4\u00f6\u00f1\u00fc\u00e0\u20ac';
let unicode = false;
for (let i = 0; i < text.length; i++) {
  const code = text.charCodeAt(i);
  if (code > 127 && GSM_EXTRA.indexOf(text.charAt(i)) === -1) { unicode = true; break; }
}
const per = unicode ? 70 : 160;

return [{ json: Object.assign({}, decided, {
  reply_text: text,
  is_unicode: unicode,
  segments: Math.max(1, Math.ceil(text.length / per)),
}) }];
